import { useEffect, useState } from "react";

export default function FeedbackForm({ order }) {
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [alreadyGiven, setAlreadyGiven] = useState(false);

  useEffect(() => {
    checkExisting();
  }, []);

  const checkExisting = async () => {
    const res = await fetch(
      `http://127.0.0.1:8000/api/feedback/${order.order_id}/`
    );
    const data = await res.json();
    if (data.exists) {
      setAlreadyGiven(true);
    }
  };

  const submitFeedback = async () => {
    const res = await fetch("http://127.0.0.1:8000/api/feedback/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        order_id: order.order_id,
        user: order.user,
        rating,
        comment
      })
    });

    if (res.ok) {
      setSubmitted(true);
      setAlreadyGiven(true);
    }
  };

  if (alreadyGiven) return <p>✅ Feedback already submitted</p>;
  if (submitted) return <p>✅ Feedback submitted</p>;

  return (
    <div className="feedback-box">
      <h4>Give Feedback</h4>

      <select value={rating} onChange={e => setRating(Number(e.target.value))}>
        <option value={5}>⭐⭐⭐⭐⭐</option>
        <option value={4}>⭐⭐⭐⭐</option>
        <option value={3}>⭐⭐⭐</option>
        <option value={2}>⭐⭐</option>
        <option value={1}>⭐</option>
      </select>

      <br /><br />

      <textarea
        placeholder="Write comments"
        value={comment}
        onChange={e => setComment(e.target.value)}
      />

      <br /><br />

      <button onClick={submitFeedback}>Submit Feedback</button>
    </div>
  );
}
